function renderPlannerQualityPanel(report){const heavy=report.dayMetrics.filter(d=>d.level==='heavy');const duplicateLines=report.duplicates.map(d=>`<li>${escapeHtml(d.list[0].name)} — appears on ${d.list.map(x=>`Day ${x.day}`).join(', ')}</li>`).join('');const loadLines=report.dayMetrics.map(d=>`<li><strong>Day ${d.day}:</strong> ${d.activities} activities · ${d.filledSlots}/3 time slots · ${d.level} load</li>`).join('');const recommendations=plannerRecommendations(report);const recommendationLines=recommendations.map(r=>`<li>${escapeHtml(r.text)}</li>`).join('');return `<section class="planner-quality" aria-live="polite"><strong>🧭 Itinerary check</strong><p>${report.totalActivities} activities across ${report.dayMetrics.length} days. This is a planning heuristic, not a travel-time estimate.</p><ul>${loadLines}</ul><p class="planner-note">Addresses are used for practical planning. This itinerary does not use GPS address data or calculate routes; confirm travel time with a map or transit app.</p>${report.duplicates.length?`<div class="planner-quality-warning"><strong>Possible duplicates</strong><ul>${duplicateLines}</ul></div>`:'<p class="planner-quality-ok">✓ No repeated activity names detected.</p>'}${heavy.length?`<div class="planner-quality-warning"><strong>Busy days</strong><p>${heavy.map(d=>`Day ${d.day}`).join(', ')} may be overloaded. Consider leaving more flexibility.</p></div>`:''}${recommendations.length?`<div class="planner-quality-recommendations"><strong>💡 Suggested adjustments</strong><ul>${recommendationLines}</ul><button class="secondary" onclick="document.querySelector('.planner-attraction-picker')?.scrollIntoView({behavior:'smooth',block:'start'})">Review attractions</button></div>`:'<p class="planner-quality-ok">✓ Your itinerary has no obvious planning flags.</p>'}</section>${cmePhase79Render(cmePhase79Assess(currentItineraryDays,document.getElementById('planner-city')?.value||'Shanghai'))}${cmePhase80RenderPanel()}${cmePhase81Render()}${cmePhase82Render()}${cmePhase83Render()}`;}

function plannerSnapshotKey(snapshot){return JSON.stringify(snapshot);}
function plannerHistoryReset(){plannerHistory=[];plannerHistoryCursor=-1;}
function plannerHistoryCommit(label='Edit itinerary'){const snapshot=plannerSnapshot();const key=plannerSnapshotKey(snapshot);if(plannerHistoryCursor>=0&&plannerSnapshotKey(plannerHistory[plannerHistoryCursor].snapshot)===key)return;if(plannerHistoryCursor<plannerHistory.length-1)plannerHistory=plannerHistory.slice(0,plannerHistoryCursor+1);plannerHistory.push({label,snapshot,at:new Date().toISOString()});if(plannerHistory.length>PLANNER_HISTORY_LIMIT)plannerHistory.shift();plannerHistoryCursor=plannerHistory.length-1;plannerHistoryUpdateControls();schedulePlannerAutosave(label);}
function plannerHistoryUpdateControls(){const undo=document.getElementById('planner-undo');const redo=document.getElementById('planner-redo');if(undo)undo.disabled=plannerHistoryCursor<=0;if(redo)redo.disabled=plannerHistoryCursor<0||plannerHistoryCursor>=plannerHistory.length-1;const status=document.getElementById('planner-history-status');if(status)status.textContent=plannerHistoryCursor>=0?`History ${plannerHistoryCursor+1}/${plannerHistory.length}${plannerHistory[plannerHistoryCursor]?.label?` · ${plannerHistory[plannerHistoryCursor].label}`:''}`:'History not available';}
function plannerHistoryRestore(index){if(index<0||index>=plannerHistory.length)return;plannerHistoryCursor=index;const snapshot=plannerHistory[index].snapshot;document.getElementById('planner-city').value=snapshot.city;document.getElementById('planner-days').value=String(snapshot.days.length||1);document.getElementById('planner-style').value=snapshot.style;currentItineraryDays=snapshot.days.map(d=>({...d}));currentDayLocks=snapshot.dayLocks.slice();currentPinnedSlots=snapshot.pinnedSlots.slice();renderEditableItinerary(snapshot.city,snapshot.days.length,snapshot.style,snapshot.days);plannerHistoryUpdateControls();}
function plannerUndo(){if(plannerHistoryCursor>0)plannerHistoryRestore(plannerHistoryCursor-1);}
function plannerRedo(){if(plannerHistoryCursor<plannerHistory.length-1)plannerHistoryRestore(plannerHistoryCursor+1);}

function visualSlotContent(value){return plannerActivityNames(value);}
function visualEstimatedHours(day){return ['morning','afternoon','evening'].reduce((sum,key)=>sum+plannerActivityNames(day[key]).length*(key==='evening'?1.5:2),0);}
function renderVisualItinerary(days,report){const slots=[['morning','🌤️','Morning'],['afternoon','☀️','Afternoon'],['evening','🌙','Evening']];const maxHours=8;const cards=days.map((day,i)=>{const metric=report.dayMetrics[i];const estimated=visualEstimatedHours(day);const level=metric.level;const items=slots.map(([key,icon,label])=>{const names=visualSlotContent(day[key]);return `<div class="visual-slot"><span class="visual-slot-icon">${icon}</span><div class="visual-slot-body"><strong>${label}</strong><p class="${names.length?'':'empty'}">${names.length?names.map(escapeHtml).join('<br>'):'Flexible time · not planned yet'}</p></div></div>`;}).join('');return `<article class="visual-day-card ${level==='heavy'?'is-heavy':''}"><div class="visual-day-top"><strong>Day ${i+1}${currentDayLocks[i]?' 🔒':''}</strong><small>${metric.activities} activities · ${level}</small></div>${items}<div class="visual-day-footer">Estimated activity load · ${estimated.toFixed(1)}h<div class="visual-load-bar"><span style="width:${Math.min(100,estimated/maxHours*100)}%"></span></div>${estimated>maxHours?'⚠️ May feel over-packed':estimated===0?'Keep this day flexible':'Plan buffer time between activities'}</div></article>`;}).join('');const heavy=report.dayMetrics.filter(d=>d.level==='heavy');return `<section class="visual-itinerary" aria-label="Visual itinerary"><div class="visual-itinerary-head"><div><h4>🗓️ Your trip at a glance</h4><p>Timeline overview · activity load is an estimate, not travel-time data.</p></div><div class="visual-itinerary-controls"><button type="button" onclick="setVisualItineraryMode('timeline')" aria-pressed="true" id="visual-mode-timeline">Timeline</button><button type="button" onclick="setVisualItineraryMode('calendar')" aria-pressed="false" id="visual-mode-calendar">Calendar</button></div></div>${heavy.length?`<div class="visual-itinerary-warning">⚠️ ${heavy.map(d=>`Day ${d.day}`).join(', ')} ${heavy.length===1?'looks':'look'} busy. Consider adding buffer time or moving an activity.</div>`:''}<div class="visual-calendar" id="visual-itinerary-grid">${cards}</div></section>`;}
function setVisualItineraryMode(mode){const grid=document.getElementById('visual-itinerary-grid');if(!grid)return;grid.classList.toggle('calendar-mode',mode==='calendar');document.getElementById('visual-mode-timeline')?.setAttribute('aria-pressed',String(mode==='timeline'));document.getElementById('visual-mode-calendar')?.setAttribute('aria-pressed',String(mode==='calendar'));}
const CME_LOGISTICS_CHECKLIST_ITEMS=[['passport','Passport and booking identity details'],['payments','Payment setup (Alipay / WeChat Pay and backup card)'],['connectivity','Connectivity plan (SIM / eSIM / roaming)'],['transit','Install or prepare city transport and map tools'],['booking','Check attraction reservations, tickets and entry rules'],['addresses','Save hotel and attraction addresses in Chinese offline'],['buffer','Leave transport buffer and confirm last-mile access']];
function logisticsChecklistKey(city){return `cme-logistics-checklist-v1:${city}`;}
function getLogisticsChecklist(city){try{return JSON.parse(CMEStorage.getItem(logisticsChecklistKey(city))||'{}')||{};}catch(e){return {};}}
function toggleLogisticsChecklist(city,item,checked){const state=getLogisticsChecklist(city);state[item]=!!checked;try{CMEStorage.setItem(logisticsChecklistKey(city),JSON.stringify(state));}catch(e){}const panel=document.querySelector('.planner-logistics');if(panel)panel.outerHTML=renderTravelLogistics(city);renderMyChina();}
function plannerLogisticsBookingItems(city){const records=plannerPickerRecords(city)||[];const names=currentItineraryDays.flatMap(day=>['morning','afternoon','evening'].flatMap(key=>plannerActivityNames(day[key])));const norm=plannerNormalizeActivity;const matched=records.filter(r=>names.some(n=>norm(n).includes(norm(r.name))||norm(r.name).includes(norm(n))));return [...new Map(matched.map(r=>[r.name,r])).values()].slice(0,8);}
function plannerTransitAdvice(city){const advice={Shanghai:['Metro is useful for longer cross-city trips; walk within compact neighbourhoods.','For riverfront or Pudong visits, confirm the crossing and last-mile route before leaving.'],Beijing:['Use metro for major urban corridors and allow extra time for large station transfers.','For Great Wall or suburban attractions, plan a dedicated day and verify the section, departure point and return transport.'],Guangzhou:['Metro is a practical backbone for city visits; combine nearby attractions on foot.','For riverfront or outlying destinations, verify the last-mile connection and return options.'],Shenzhen:['Metro and walking work well for central clusters; check park entrances and the distance between waterfront sections.','For destinations spread across the city, group by district rather than making repeated cross-city trips.'],Chengdu:['Metro and walking can cover central clusters; use a separate plan for suburban attractions such as the Panda Base.','Confirm the exact entrance and return transport for large parks or heritage sites.'],Chongqing:['Expect steep terrain, stairs and multi-level pedestrian routes; map the exact entrance and exit.','Metro, cableways and ride-hailing may complement walking; verify operating status and queue conditions.'],Harbin:['Metro and walking are useful in central areas; in winter, reduce walking distances and add warm-up stops.','Check weather, ice conditions and seasonal attraction operations before committing to outdoor plans.'],Xinjiang:['Treat Xinjiang as a region, not a compact city itinerary. Distances between destinations can be substantial.','Plan intercity transfers, overnight stays, seasonal road conditions and local access separately; do not rely on city transit assumptions.']};return advice[city]||['Use public transit for longer trips and walk within nearby attraction clusters.','Verify the exact entrance, last-mile route and return options before leaving.'];}
function renderTravelLogistics(city){const checklist=getLogisticsChecklist(city);const done=CME_LOGISTICS_CHECKLIST_ITEMS.filter(([id])=>checklist[id]).length;const advice=plannerTransitAdvice(city);const bookings=plannerLogisticsBookingItems(city);const bookingHtml=bookings.length?bookings.map(r=>`<li><strong>${escapeHtml(r.name)}</strong><br><span class="planner-booking-status">Check official booking / entry rules</span></li>`).join(''):'<li>No attraction-specific booking reminders could be matched to the current itinerary. Review each venue before travel.</li>';const checks=CME_LOGISTICS_CHECKLIST_ITEMS.map(([id,label])=>`<label class="${checklist[id]?'is-checked':''}"><input type="checkbox" ${checklist[id]?'checked':''} onchange="toggleLogisticsChecklist('${escapeHtml(city)}','${id}',this.checked)"><span>${escapeHtml(label)}</span></label>`).join('');return `<section class="planner-logistics" aria-label="Travel logistics"><div class="planner-logistics-head"><div><h4>🧳 Travel logistics</h4><p>Practical reminders for ${escapeHtml(city)}. These are planning prompts—not live route, transit or booking availability.</p></div><strong>${done}/${CME_LOGISTICS_CHECKLIST_ITEMS.length} ready</strong></div><div class="planner-logistics-progress"><span style="width:${done/CME_LOGISTICS_CHECKLIST_ITEMS.length*100}%"></span></div><div class="planner-logistics-grid"><article class="planner-logistics-card"><h5>🚇 Getting around</h5><ul>${advice.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul><p class="planner-logistics-note">Route times, fares, service status and directions are not live-connected. Confirm with your map or transit app on the day.</p></article><article class="planner-logistics-card"><h5>🎟️ Booking & entry reminders</h5><ul>${bookingHtml}</ul><p class="planner-logistics-note">A reminder does not mean booking is required. Requirements vary by venue and may change; use the official venue channel.</p></article><article class="planner-logistics-card"><h5>✅ Before you go</h5><div class="planner-logistics-checklist">${checks}</div></article><article class="planner-logistics-card"><h5>🕒 Buffer time</h5><ul><li>Keep a buffer between activities for transfers, queues, meals and finding entrances.</li><li>Large attractions and regional trips may need more time than the slot suggests.</li><li>Confirm opening hours and the final return option before leaving your accommodation.</li></ul></article></div></section>`;}
function cmePhase90ContextCategories(city){const names=currentItineraryDays.flatMap(d=>['morning','afternoon','evening'].flatMap(k=>plannerActivityNames(d[k]||'')));const records=attractionData?.[city]||[];const cats=new Set();records.filter(r=>names.some(n=>n.toLowerCase()===attractionName(r).toLowerCase())).forEach(r=>cmePhase89Categories(r).forEach(c=>cats.add(c)));return {names:new Set(names.map(n=>n.toLowerCase())),cats,records};}
function cmePhase90SeasonBonus(item,season){if(!season||season==='any')return 0;const text=cmePhase88Text(item);const terms={spring:['spring','blossom','flower','peach','cherry'],summer:['summer','water','beach','shade','cool'],autumn:['autumn','fall','red leaves','harvest'],winter:['winter','snow','ice','hot spring']};const hits=(terms[season]||[]).filter(t=>text.includes(t));return hits.length?Math.min(3,hits.length):0;}
function cmePhase90Rank(city,season='any',limit=5){const ctx=cmePhase90ContextCategories(city),profile=CMEProfile.read(),settings=cmePhase88Load(),diversity=Number(settings.diversity)||45;const candidates=ctx.records.filter(item=>!ctx.names.has(attractionName(item).toLowerCase())).map(item=>{const explain=cmePhase87Explain(item,city),cats=cmePhase89Categories(item),novel=cats.filter(c=>!ctx.cats.has(c)),seasonBonus=cmePhase90SeasonBonus(item,season),categoryBonus=Math.min(4,novel.length*2),pacePenalty=(document.getElementById('planner-style')?.value==='relaxed'&&/theme park|large park|full day/i.test(cmePhase88Text(item)))?2:0,score=explain.score+categoryBonus+seasonBonus-pacePenalty;return {item,score,explain,cats,novel,seasonBonus,categoryBonus,pacePenalty};}).filter(x=>!x.explain.excluded&&x.explain.score>-100).sort((a,b)=>b.score-a.score);return cmePhase89DiversitySelect(candidates.map(x=>({...x,city,cats:x.cats})),diversity,limit).map(x=>({...x,contextReasons:[x.novel.length?'Adds '+x.novel.join(', '):'Fits existing trip themes',x.seasonBonus?'Season-related keywords found':'No seasonal signal in content',x.pacePenalty?'May be demanding for relaxed pace':'Pace appears compatible']}));}
function cmePhase90Add(itemId,dayIndex){const city=document.getElementById('planner-city')?.value||'Shanghai',day=currentItineraryDays[dayIndex];if(!day||currentDayLocks[dayIndex])return;const record=(attractionData?.[city]||[]).find(x=>String(x.id||x.slug||attractionName(x))===String(itemId));if(!record)return;const slot=['morning','afternoon','evening'].find(k=>!day[k]?.trim()&&!plannerSlotPinned(dayIndex,k));if(!slot){alert('This day has no empty flexible slot. Please choose another day or clear a slot first.');return;}plannerHistoryCommit('Before Phase 90 contextual recommendation');day[slot]=attractionName(record);renderEditableItinerary(city,currentItineraryDays.length,document.getElementById('planner-style')?.value||'balanced',currentItineraryDays);plannerHistoryCommit('Add contextual recommendation');}
function cmePhase90RenderPanel(city){if(!currentItineraryDays.length)return '';const ctx=cmePhase90ContextCategories(city),season=document.getElementById('cme-phase90-season')?.value||'any',dayOptions=currentItineraryDays.map((d,i)=>`<option value="${i}" ${currentDayLocks[i]?'disabled':''}>Day ${i+1}${currentDayLocks[i]?' · locked':''}</option>`).join(''),ranked=cmePhase90Rank(city,season,5),seasonSelect=`<select id="cme-phase90-season" onchange="cmePhase90Refresh()"><option value="any" ${season==='any'?'selected':''}>Any season</option><option value="spring" ${season==='spring'?'selected':''}>Spring</option><option value="summer" ${season==='summer'?'selected':''}>Summer</option><option value="autumn" ${season==='autumn'?'selected':''}>Autumn</option><option value="winter" ${season==='winter'?'selected':''}>Winter</option></select>`;return `<section class="cme-phase90-panel"><strong>🧭 Context-aware recommendations · Phase 90</strong><p>Suggestions complement this trip—not just your profile. Already planned activities are excluded; missing experience categories receive a modest bonus.</p><div class="cme-phase90-controls"><label>Season context ${seasonSelect}</label><label>Add to day<select id="cme-phase90-day">${dayOptions||'<option>No flexible day</option>'}</select></label><button type="button" class="secondary" onclick="cmePhase90Refresh()">Refresh suggestions</button></div><div class="cme-phase90-context">${ctx.cats.size?[...ctx.cats].map(c=>`<span>Included: ${escapeHtml(c)}</span>`).join(''):'<span>No categories detected from current itinerary</span>'}<span>${ctx.names.size} planned activity name(s)</span></div>${ranked.length?`<div class="cme-phase90-list">${ranked.map(x=>`<article class="cme-phase90-item"><strong>${escapeHtml(attractionName(x.item))}</strong><small>Context score ${Math.round(x.score)} · ${escapeHtml(x.contextReasons.join(' · '))}</small><button type="button" class="secondary" onclick="cmePhase90Add(decodeURIComponent('${encodeURIComponent(String(x.item.id||x.item.slug||attractionName(x.item)))}'),Number(document.getElementById('cme-phase90-day')?.value||0))">Add to selected day</button></article>`).join('')}</div>`:'<p>No additional candidates found in the current attraction data. Try another season or clear a slot.</p>'}<p class="cme-phase90-note">Seasonal matching uses text keywords only. This does not verify seasonal operation, weather, opening hours, travel times or availability. Locked days are unavailable for insertion; pinned slots are protected.</p></section>`;}
function cmePhase90Refresh(){const city=document.getElementById('planner-city')?.value||'Shanghai';const season=document.getElementById('cme-phase90-season')?.value||'any';const panel=document.querySelector('.cme-phase90-panel');if(panel){panel.outerHTML=cmePhase90RenderPanel(city);const next=document.getElementById('cme-phase90-season');if(next)next.value=season;}}

/* Phase 91 — trip-aware day fit */

function cmePhase91DayFit(item,day,index,city){const slots=['morning','afternoon','evening'],activities=slots.flatMap(k=>plannerActivityNames(day?.[k]||'')),empty=slots.filter(k=>!String(day?.[k]||'').trim()&&!plannerSlotPinned(index,k)),locked=!!currentDayLocks[index],itemCats=cmePhase89Categories(item),records=attractionData?.[city]||[],planned=activities.map(name=>records.find(r=>attractionName(r).toLowerCase()===name.toLowerCase())).filter(Boolean),dayCats=new Set(planned.flatMap(r=>cmePhase89Categories(r))),novel=itemCats.filter(c=>!dayCats.has(c)),load=activities.length;let score=100-load*20+Math.min(12,novel.length*4);if(load===0)score-=5;if(empty.length===0)score-=60;if(locked)score=-999;const reasons=[locked?'Day locked':empty.length?`${empty.length} flexible slot(s) available`:'No empty flexible slot',load===0?'Day is currently free':`${load} planned activity slot(s)`];if(novel.length)reasons.push(`Adds ${novel.join(', ')}`);else if(itemCats.length)reasons.push('Similar category already present');reasons.push('Address and travel logistics require manual review');return {day:index,score,valid:!locked&&empty.length>0,emptySlots:empty,load,nearestKm:null,novelCategories:novel,reasons};}
function cmePhase91RankDays(item,city){return currentItineraryDays.map((day,index)=>cmePhase91DayFit(item,day,index,city)).filter(x=>x.valid).sort((a,b)=>b.score-a.score);}
function cmePhase91BestDay(item,city){return cmePhase91RankDays(item,city)[0]||null;}
function cmePhase91Add(itemId,dayIndex){const city=document.getElementById('planner-city')?.value||'Shanghai',day=currentItineraryDays[dayIndex];if(!day||currentDayLocks[dayIndex])return;const record=(attractionData?.[city]||[]).find(x=>String(x.id||x.slug||attractionName(x))===String(itemId));if(!record)return;const slot=['morning','afternoon','evening'].find(k=>!day[k]?.trim()&&!plannerSlotPinned(dayIndex,k));if(!slot){alert('No empty flexible slot is available on this day.');return;}plannerHistoryCommit('Before Phase 91 trip-aware recommendation');day[slot]=attractionName(record);renderEditableItinerary(city,currentItineraryDays.length,document.getElementById('planner-style')?.value||'balanced',currentItineraryDays);plannerHistoryCommit('Add trip-aware recommendation');}
function cmePhase91RenderPanel(city){if(!currentItineraryDays.length)return '';const season=document.getElementById('cme-phase90-season')?.value||'any',ranked=cmePhase90Rank(city,season,6),items=ranked.map(x=>({...x,dayFit:cmePhase91BestDay(x.item,city)})).filter(x=>x.dayFit).sort((a,b)=>b.dayFit.score-a.dayFit.score);const busy=currentItineraryDays.map((d,i)=>({i,count:['morning','afternoon','evening'].flatMap(k=>plannerActivityNames(d[k]||'')).length,locked:!!currentDayLocks[i]}));return `<section class="cme-phase91-panel"><strong>🗓️ Trip-aware day matching · Phase 91</strong><p>Recommendations are matched to your itinerary’s available capacity and category gaps. Addresses and transfers require manual review.</p><div class="cme-phase91-day-summary">${busy.map(d=>`<span class="${d.locked?'locked':''}">Day ${d.i+1}: ${d.locked?'Locked':d.count+'/3 slots used'}</span>`).join('')}</div>${items.length?`<div class="cme-phase91-list">${items.map(x=>{const fit=x.dayFit,day=currentItineraryDays[fit.day],slot=fit.emptySlots[0],dayName=`Day ${fit.day+1} · ${slot}`;return `<article class="cme-phase91-item"><strong>${escapeHtml(attractionName(x.item))}</strong><div class="cme-phase91-fit"><span>Best fit: ${escapeHtml(dayName)}</span><span>Fit score ${Math.round(fit.score)}</span></div><small>${escapeHtml(fit.reasons.join(' · '))}</small><button type="button" class="secondary" onclick="cmePhase91Add(decodeURIComponent('${encodeURIComponent(String(x.item.id||x.item.slug||attractionName(x.item)))}'),${fit.day})">Add to Day ${fit.day+1} (${slot})</button></article>`;}).join('')}</div>`:'<p>No recommendation has a compatible day slot. Unlock a day or free a flexible slot to continue.</p>'}<p class="cme-phase91-note">Address-first planning is used; no distance calculation is performed. Activity count and category matches are estimates; travel time, opening hours, ticket availability and actual routes are not verified.</p></section>`;}
/* Phase 92 — daily route and time budget heuristics */
function cmePhase92FindRecord(city,name){const records=attractionData?.[city]||[];const n=String(name||'').trim().toLowerCase();return records.find(r=>attractionName(r).trim().toLowerCase()===n)||records.find(r=>n&&attractionName(r).trim().toLowerCase().includes(n))||null;}
function cmePhase92DurationHours(name,record,slot){const display=String(record?.visitDuration?.display||record?.duration||'');const range=display.match(/(\d+(?:\.\d+)?)\s*(?:–|-|to)\s*(\d+(?:\.\d+)?)\s*(hours?|hrs?|分钟|minutes?)/i);if(range){const mid=(Number(range[1])+Number(range[2]))/2;return /min|分钟/i.test(range[3])?mid/60:mid;}const single=display.match(/(\d+(?:\.\d+)?)\s*(hours?|hrs?|分钟|minutes?)/i);if(single)return /min|分钟/i.test(single[2])?Number(single[1])/60:Number(single[1]);const text=(String(name)+' '+String(record?.category||'')+' '+String(record?.summary?.en||'')).toLowerCase();if(/theme park|full day|day trip|great wall|large park|zoo|national park/.test(text))return 4.5;if(/museum|palace|temple|heritage|historic|garden|park/.test(text))return 2.5;if(/market|street|neighbourhood|waterfront|promenade|viewpoint|tower/.test(text))return 1.5;if(slot==='evening')return 1.5;return 2;}
function cmePhase92SlotBudget(slot){return slot==='morning'?4:slot==='afternoon'?4:3;}
function cmePhase92DayAnalysis(day,index,city,pace='balanced'){const slots=['morning','afternoon','evening'],records=[],slotResults=[];slots.forEach(slot=>{const names=plannerActivityNames(day?.[slot]||''),matched=names.map(name=>({name,record:cmePhase92FindRecord(city,name),hours:cmePhase92DurationHours(name,cmePhase92FindRecord(city,name),slot)}));const hours=matched.reduce((sum,x)=>sum+x.hours,0);slotResults.push({slot,names,hours,budget:cmePhase92SlotBudget(slot),over:hours>cmePhase92SlotBudget(slot)});matched.forEach(x=>{if(x.record)records.push(x.record);});});const transferHours=Math.max(0,records.length-1)*0.5;const distances=[];const activityHours=slotResults.reduce((s,x)=>s+x.hours,0),totalHours=activityHours+transferHours,limits={relaxed:7.5,balanced:9.5,intensive:11.5},limit=limits[pace]||limits.balanced,locked=!!currentDayLocks[index],warnings=[];slotResults.filter(x=>x.over).forEach(x=>warnings.push(`${x.slot} exceeds its ${x.budget}h planning window`));if(totalHours>limit)warnings.push(`Estimated ${totalHours.toFixed(1)}h exceeds ${pace} pace target (${limit}h)`);if(records.length>1)warnings.push('Transfer buffer is a generic planning allowance; verify travel time manually.');if(locked)warnings.push('Day is locked; analysis only');return {day:index,slots:slotResults,activityHours,transferHours,totalHours,limit,pace,distances,warnings,locked,activityCount:slotResults.reduce((n,x)=>n+x.names.length,0)};}
function cmePhase92AllDays(city,pace='balanced'){return currentItineraryDays.map((day,index)=>cmePhase92DayAnalysis(day,index,city,pace));}
function cmePhase92Refresh(){const city=document.getElementById('planner-city')?.value||'Shanghai',panel=document.querySelector('.cme-phase92-panel');if(panel)panel.outerHTML=cmePhase92RenderPanel(city);}
function cmePhase92RenderPanel(city){if(!currentItineraryDays.length)return '';const pace=document.getElementById('cme-phase92-pace')?.value||document.getElementById('planner-style')?.value||'balanced',analyses=cmePhase92AllDays(city,pace),total=analyses.reduce((s,x)=>s+x.totalHours,0),warnDays=analyses.filter(x=>x.warnings.length).length;return `<section class="cme-phase92-panel"><strong>⏱️ Daily route & time budget · Phase 92</strong><p>Estimate visit durations, slot load and approximate transfer buffers to spot days that may feel rushed. These are planning heuristics, not live route times.</p><div class="cme-phase92-controls"><label>Travel pace<select id="cme-phase92-pace" onchange="cmePhase92Refresh()"><option value="relaxed" ${pace==='relaxed'?'selected':''}>Relaxed · 7.5h target</option><option value="balanced" ${pace==='balanced'?'selected':''}>Balanced · 9.5h target</option><option value="intensive" ${pace==='intensive'?'selected':''}>Intensive · 11.5h target</option></select></label><span>${analyses.length} day(s) · ${total.toFixed(1)} estimated hours · ${warnDays} day(s) with alerts</span></div><div class="cme-phase92-days">${analyses.map(a=>`<article class="cme-phase92-day"><header>Day ${a.day+1} · ${a.totalHours.toFixed(1)}h estimate <span class="${a.warnings.length?'warn':''}">${a.warnings.length?a.warnings.length+' alert(s)':'Within pace target'}</span></header><div class="cme-phase92-slots">${a.slots.map(x=>`<div class="cme-phase92-slot"><b>${x.slot[0].toUpperCase()+x.slot.slice(1)} · ${x.hours.toFixed(1)}h / ${x.budget}h</b><small>${x.names.length?escapeHtml(x.names.join(' · ')):'No planned activity'}${x.over?' · Slot may be overloaded':''}</small></div>`).join('')}<div class="cme-phase92-slot"><b>Transfer buffer · ${a.transferHours.toFixed(1)}h</b><small>${a.activityCount>1?'Generic buffer only; verify actual transfer times':'No transfer buffer needed'}</small></div></div>${a.warnings.length?`<small style="display:block;color:#991b1b;margin-top:7px">${escapeHtml(a.warnings.join(' · '))}</small>`:''}</article>`).join('')}</div><p class="cme-phase92-note">Visit duration uses dataset duration text when parseable, otherwise category/keyword defaults. Transfer buffers are generic editable planning allowances, not route calculations. Actual travel, traffic, queues, opening hours and meal breaks are not verified.</p></section>`;}

/* Phase 93 — preview-first flexible-slot time-budget balancing */
let cmePhase93Preview=null;
function cmePhase93Snapshot(){return JSON.stringify({days:currentItineraryDays,locks:currentDayLocks,pins:currentPinnedSlots});}
function cmePhase93IsProtected(dayIndex,slot){return !!currentDayLocks[dayIndex]||plannerSlotPinned(dayIndex,slot);}
function cmePhase93SlotValue(day,slot){return String(day?.[slot]||'').trim();}
function cmePhase93BuildPlan(city,pace='balanced'){
 const analyses=cmePhase92AllDays(city,pace),days=currentItineraryDays.map(d=>({...d})),moves=[],limits={relaxed:7.5,balanced:9.5,intensive:11.5},limit=limits[pace]||limits.balanced;
 const overDays=analyses.filter(a=>a.totalHours>limit||a.slots.some(s=>s.over)).sort((a,b)=>b.totalHours-a.totalHours);
 for(const source of overDays){
  const src=source.day;if(currentDayLocks[src])continue;
  const candidates=['morning','afternoon','evening'].filter(slot=>!cmePhase93IsProtected(src,slot)&&plannerActivityNames(days[src][slot]||'').length===1).sort((a,b)=>cmePhase92DurationHours(days[src][b],cmePhase92FindRecord(city,days[src][b]),b)-cmePhase92DurationHours(days[src][a],cmePhase92FindRecord(city,days[src][a]),a));
  for(const slot of candidates){
   const activity=plannerActivityNames(days[src][slot])[0],record=cmePhase92FindRecord(city,activity),duration=cmePhase92DurationHours(activity,record,slot);
   if(!activity||duration<0.5)continue;
   const targets=analyses.map((a,i)=>({i,a})).filter(x=>x.i!==src&&!currentDayLocks[x.i]).map(x=>{const empty=['morning','afternoon','evening'].filter(k=>!cmePhase93SlotValue(days[x.i],k)&&!cmePhase93IsProtected(x.i,k));const analysis=cmePhase92DayAnalysis(days[x.i],x.i,city,pace);const geoPenalty=0,extraTransfer=0;return {day:x.i,empty,analysis,score:(limit-analysis.totalHours)*5,extraTransfer,slotBudget:cmePhase92SlotBudget(empty[0]),slotLoad:analysis.slots.find(s=>s.slot===empty[0])?.hours||0};}).filter(x=>x.empty.length&&x.analysis.totalHours+duration+x.extraTransfer<=limit&&x.slotLoad+duration<=x.slotBudget).sort((a,b)=>b.score-a.score);
   const target=targets[0];if(!target)continue;
   moves.push({fromDay:src,fromSlot:slot,toDay:target.day,toSlot:target.empty[0],activity,durationHours:duration,sourceHoursBefore:source.totalHours,targetHoursBefore:target.analysis.totalHours});
   days[src][slot]='';days[target.day][target.empty[0]]=activity;
   break;
  }
 }
 const after=currentItineraryDays.map((d,i)=>({...days[i]}));return {moves,days:after,pace,limit,before:cmePhase92AllDays(city,pace),afterAnalysis:after.map((d,i)=>cmePhase92DayAnalysis(d,i,city,pace)),snapshot:cmePhase93Snapshot(),city};
}
function cmePhase93GeneratePreview(){const city=document.getElementById('planner-city')?.value||'Shanghai',pace=document.getElementById('cme-phase92-pace')?.value||document.getElementById('planner-style')?.value||'balanced';cmePhase93Preview=cmePhase93BuildPlan(city,pace);cmePhase93Refresh();}
function cmePhase93CancelPreview(){cmePhase93Preview=null;cmePhase93Refresh();}
function cmePhase93ApplyPreview(){const p=cmePhase93Preview;if(!p||p.snapshot!==cmePhase93Snapshot()){alert('The itinerary changed after this preview. Please generate a fresh balancing preview.');cmePhase93Preview=null;cmePhase93Refresh();return;}if(!p.moves.length){alert('No safe flexible-slot moves were found for the current itinerary.');return;}plannerHistoryCommit('Before Phase 93 time-budget balancing');currentItineraryDays=p.days.map(d=>({...d}));renderEditableItinerary(p.city,currentItineraryDays.length,document.getElementById('planner-style')?.value||'balanced',currentItineraryDays);plannerHistoryCommit('Apply Phase 93 time-budget balancing');cmePhase93Preview=null;}
function cmePhase93RenderPanel(city){if(!currentItineraryDays.length)return '';const p=cmePhase93Preview;return `<section class="cme-phase93-panel"><strong>⚖️ Time-budget auto-balancer · Phase 93</strong><p>Find overloaded days and suggest moving a single flexible activity to a lighter day with an empty slot. Locked days and pinned slots are protected. Preview before applying.</p><div class="cme-phase93-actions"><button type="button" class="secondary" onclick="cmePhase93GeneratePreview()">Generate balancing preview</button>${p?`<button type="button" class="secondary" onclick="cmePhase93CancelPreview()">Cancel preview</button>`:''}</div>${p?`<div class="cme-phase93-preview"><strong>${p.moves.length} proposed move(s) · ${p.pace} pace · ${p.limit}h target</strong>${p.moves.length?p.moves.map(m=>`<div class="cme-phase93-move"><b>${escapeHtml(m.activity)}</b><small>Day ${m.fromDay+1} ${m.fromSlot} → Day ${m.toDay+1} ${m.toSlot} · ${m.durationHours.toFixed(1)}h estimated</small></div>`).join(''):'<p>No safe moves found. Free flexible slots, unlock a day, or change pace.</p>'}<div class="cme-phase93-actions">${p.moves.length?`<button type="button" onclick="cmePhase93ApplyPreview()">Apply moves</button>`:''}<button type="button" class="secondary" onclick="cmePhase93CancelPreview()">Discard</button></div></div>`:''}<p class="cme-phase93-note">Moves are heuristic. Duration estimates are heuristic. Transfer time is not calculated; verify addresses and travel logistics manually. The balancer moves only single-activity, unpinned flexible slots into empty slots and does not automatically save the trip.</p></section>`;}
function cmePhase93Refresh(){const city=document.getElementById('planner-city')?.value||'Shanghai',panel=document.querySelector('.cme-phase93-panel');if(panel)panel.outerHTML=cmePhase93RenderPanel(city);}


// Phase 94/95 — automatic geographic sequencing and clustering intentionally removed.
function cmePhase94Render(city){return currentItineraryDays.length?'<section class="cme-phase94-panel"><strong>Manual stop ordering</strong><p>Automatic route sequencing is disabled. Review attraction addresses in an external map or transit app, then reorder activities manually.</p></section>':'';}
function cmePhase94Refresh(){const panel=document.querySelector('.cme-phase94-panel');if(panel)panel.outerHTML=cmePhase94Render(document.getElementById('planner-city')?.value||'Shanghai');}
function cmePhase95Render(city){return currentItineraryDays.length?'<section class="cme-phase95-panel"><strong>Manual day balancing</strong><p>Automatic cross-day optimization is disabled. Use visit-duration estimates, day locks and manual activity moves to balance your itinerary.</p></section>':'';}
function cmePhase95Refresh(){const panel=document.querySelector('.cme-phase95-panel');if(panel)panel.outerHTML=cmePhase95Render(document.getElementById('planner-city')?.value||'Shanghai');}
// Phase 96 — global itinerary quality scoring and actionable diagnostics (read-only)
function cmePhase96Record(city,name){return (attractionData?.[city]||[]).find(r=>attractionName(r).toLowerCase()===String(name).toLowerCase());}
function cmePhase96Analyze(city){const days=currentItineraryDays||[],pace=document.getElementById('cme-phase92-pace')?.value||document.getElementById('planner-style')?.value||'balanced',analyses=days.map((d,i)=>cmePhase92DayAnalysis(d,i,city,pace)),all=days.flatMap((d,i)=>cmePhase95Activities(d).map(x=>({...x,day:i}))),matched=all.filter(x=>x.record),coverage=all.length?matched.length/all.length:1,dayTotals=analyses.map(a=>a.totalHours),mean=dayTotals.length?dayTotals.reduce((a,b)=>a+b,0)/dayTotals.length:0,variance=dayTotals.length?dayTotals.reduce((s,x)=>s+(x-mean)**2,0)/dayTotals.length:0,loadScore=Math.max(0,35-Math.sqrt(variance)*4),cats=matched.map(x=>String(x.record.category||x.record.type||x.record.tags?.[0]||'other').toLowerCase()),unique=new Set(cats).size,varietyScore=matched.length?Math.min(30,unique/Math.max(1,Math.min(matched.length,5))*30):15,coverageScore=coverage*25,score=Math.round(Math.max(0,Math.min(100,(coverageScore+loadScore+varietyScore)/90*100))),findings=[];if(coverage<.8)findings.push({title:'Improve attraction matching',detail:`${all.length-matched.length} of ${all.length} activity entries do not match attraction records.`});const overloaded=analyses.filter(a=>a.totalHours>(pace==='relaxed'?7.5:pace==='intensive'?11.5:9.5));if(overloaded.length)findings.push({title:'Review overloaded days',detail:`Day ${overloaded.map(a=>a.day+1).join(', ')} exceed the ${pace} pace time-budget target.`});if(unique<Math.min(matched.length,3))findings.push({title:'Increase experience variety',detail:'Consider mixing culture, food, nature, neighbourhood and rest experiences.'});findings.push({title:'Review real-world logistics',detail:'Verify addresses, opening hours, tickets, booking and transfer time with current official sources or external map/transit apps.'});return {score,coverageScore,loadScore,varietyScore,coverage,mean,unique,total:all.length,matched:matched.length,analyses,findings};}
function cmePhase96Render(city){if(!currentItineraryDays.length)return '';const a=cmePhase96Analyze(city);return `<section class="cme-phase96-panel"><strong>🧠 Itinerary readiness score · Phase 96</strong><p>Read-only diagnostic based on attraction matching, estimated daily time balance and activity-category variety. It does not use geographic coordinates or calculate routes.</p><div class="cme-phase96-grid"><div class="cme-phase96-card"><small>Overall heuristic score</small><strong>${a.score}/100</strong></div><div class="cme-phase96-card"><small>Attraction matching</small><strong>${Math.round(a.coverage*100)}%</strong><small>${a.matched}/${a.total} matched</small></div><div class="cme-phase96-card"><small>Daily load balance</small><strong>${Math.round(a.loadScore)}/35</strong></div><div class="cme-phase96-card"><small>Category variety</small><strong>${Math.round(a.varietyScore)}/30</strong><small>${a.unique} category labels</small></div></div><div class="cme-phase96-findings">${a.findings.map(f=>`<div class="cme-phase96-finding"><b>${escapeHtml(f.title)}</b><small>${escapeHtml(f.detail)}</small></div>`).join('')}</div><p class="cme-phase96-note">This score is a heuristic, not a travel guarantee. It does not include live transit, route distances, opening hours, booking availability, weather or accessibility. Verify logistics manually with current sources.</p></section>`;}

function renderEditableItinerary(city,days,style,slots){
 const result=document.getElementById('planner-result');
 const safeCity=escapeHtml(cmeLocalizedCity(city));
 const previousCount=currentItineraryDays.length;
 currentItineraryDays=slots.map(day=>({morning:String(day.morning||''),afternoon:String(day.afternoon||''),evening:String(day.evening||'')}));
 if(previousCount!==currentItineraryDays.length){currentDayLocks=Array(currentItineraryDays.length).fill(false);currentPinnedSlots=[];}else{currentDayLocks=currentDayLocks.slice(0,currentItineraryDays.length);while(currentDayLocks.length<currentItineraryDays.length)currentDayLocks.push(false);currentPinnedSlots=currentPinnedSlots.filter(id=>Number(id.split(':')[0])<currentItineraryDays.length);}
 let html=`<h3>${safeCity} · ${days}-day suggested itinerary</h3><p class="planner-note">Edit activities. Pin individual time slots or lock a whole day to protect it from accidental edits.</p>`;
 const quality=plannerQualityReport(currentItineraryDays);html+=renderVisualItinerary(currentItineraryDays,quality);html+=renderTravelLogistics(city);currentItineraryDays.forEach((day,i)=>{const locked=currentDayLocks[i];const metric=quality.dayMetrics[i];html+=`<article class="planner-day ${locked?'planner-day-locked':''}" data-day="${i}"><h3>Day ${i+1} ${locked?'🔒 Locked':''} <small class="planner-load planner-load-${metric.level}">${metric.activities} activities · ${metric.level} load</small></h3><div class="planner-actions"><button class="secondary" onclick="togglePlannerDayLock(${i})">${locked?'🔓 Unlock day':'🔒 Lock day'}</button><button class="secondary cme-phase78-regenerate" onclick="cmePhase78RegenerateDay(${i})" ${locked?'disabled':''}>✨ Regenerate day</button></div>${['morning','afternoon','evening'].map(key=>{const pinned=plannerSlotPinned(i,key);return `<div class="planner-slot"><strong>${key.charAt(0).toUpperCase()+key.slice(1)} ${pinned?'📌 Pinned':''}</strong><textarea aria-label="Day ${i+1} ${key}" data-slot="${key}" ${locked||pinned?'disabled':''} oninput="updateItinerarySlot(${i},'${key}',this.value)">${escapeHtml(day[key])}</textarea><button class="secondary" onclick="togglePlannerSlotPin(${i},'${key}')">${pinned?'Unpin slot':'📌 Pin slot'}</button></div>`;}).join('')}<div class="planner-actions"><button class="secondary" onclick="moveItineraryDay(${i},-1)" ${i===0||locked||currentDayLocks[i-1]?'disabled':''}>↑ Move up</button><button class="secondary" onclick="moveItineraryDay(${i},1)" ${i===currentItineraryDays.length-1||locked||currentDayLocks[i+1]?'disabled':''}>↓ Move down</button><button class="secondary" onclick="removeItineraryDay(${i})" ${locked?'disabled':''}>Remove day</button></div></article>`;});
 html+=renderAttractionPicker(city);
 html+=renderPlannerQualityPanel(plannerQualityReport(currentItineraryDays));html+=`<section class="planner-quality"><strong>Address-first planning</strong><p>China Made Easy does not store attraction GPS address data or calculate geographic routes. Review each attraction address and use your preferred map or transit app for current directions and travel times.</p></section>`;
 html+=`<div class="planner-note">Suggested itinerary only. Check attraction opening days, ticket reservations, travel time, weather and current access before finalising. For Xinjiang, select a regional cluster rather than treating the region as a single compact destination.</div>`;
 result.innerHTML=html+`<div class="planner-actions"><label style="display:grid;gap:6px;min-width:220px;font-weight:700;color:var(--muted)">Trip name<input id="planner-trip-name" type="text" maxlength="80" placeholder="e.g. Beijing Spring Trip" style="padding:10px;border:1px solid var(--line);border-radius:10px;font:inherit"></label><button class="secondary" id="planner-undo" onclick="plannerUndo()" disabled>↶ Undo</button><button class="secondary" id="planner-redo" onclick="plannerRedo()" disabled>↷ Redo</button><span id="planner-history-status" class="planner-note" style="margin:0;padding:8px 10px"></span><button class="secondary" onclick="smartDistributeAttractions()">✨ Smart distribute attractions</button><button class="secondary" onclick="smartReplanFlexibleSlots()">🧠 Replan flexible slots</button><button class="secondary" onclick="addPlannerDay()">＋ Add day</button><button class="secondary" onclick="saveItinerary()">Save as new trip</button><span id="planner-save-feedback" class="planner-note" role="status" aria-live="polite" style="margin:0;padding:8px 10px"></span><button class="secondary" onclick="saveTripVersion()">Save version</button><span id="planner-autosave-status" class="planner-note" role="status" aria-live="polite">Autosave ready · local only</span><button class="secondary" onclick="copyItinerary()">Copy itinerary</button><button class="secondary" onclick="window.print()">Print / PDF</button></div><div class="planner-saved-trips" id="planner-saved-trips"></div><div class="planner-saved-trips" id="planner-version-panel"></div><section id="route-intelligence-report" class="planner-note" aria-live="polite"></section>`;bindPlannerPickerActions();renderSavedTripsList();updateTripVersionPanel();const tripNameInput=document.getElementById('planner-trip-name');if(tripNameInput)tripNameInput.addEventListener('input',()=>schedulePlannerAutosave('Rename trip'));plannerHistoryCommit('Render / edit itinerary');
}




