function cmePhase74SaveState(v){try{localStorage.setItem(CME_PHASE74_KEY,JSON.stringify(v))}catch(e){}}
function cmePhase74Entry(id){return (cmePhase74Load().entries||[]).find(x=>x.id===id)||null;}
function cmePhase74Label(status){return ({visited:'Visited',wishlist:'Wishlist',notInterested:'Not interested',favorite:'Favorite'})[status]||'Unmarked';}
function cmePhase74Save(){const id=document.getElementById('cme-phase74-attraction')?.value||'',status=document.getElementById('cme-phase74-status')?.value||'wishlist',rating=Number(document.getElementById('cme-phase74-rating')?.value||0),note=(document.getElementById('cme-phase74-note')?.value||'').trim();if(!id){const el=document.getElementById('cme-phase74-feedback');if(el)el.textContent='Choose an attraction first.';return;}const r=cmePhase72FlattenAttractions().find(x=>x.id===id),d=cmePhase74Load();d.entries=d.entries||[];const old=d.entries.find(x=>x.id===id);const item={id,name:r?.names?.en||id,city:r?._cityName||r?.cityId||'',status,rating,note,updatedAt:new Date().toISOString(),createdAt:old?.createdAt||new Date().toISOString()};d.entries=d.entries.filter(x=>x.id!==id);if(status!=='unmarked'||rating||note)d.entries.push(item);cmePhase74SaveState(d);const el=document.getElementById('cme-phase74-feedback');if(el)el.textContent='Travel memory saved locally. Recommendations will use this feedback.';cmePhase62RenderDayMap(cmePhase63State().selectedDay);}
function cmePhase74LoadSelected(){const id=document.getElementById('cme-phase74-attraction')?.value||'',e=cmePhase74Entry(id);const status=document.getElementById('cme-phase74-status'),rating=document.getElementById('cme-phase74-rating'),note=document.getElementById('cme-phase74-note');if(status)status.value=e?.status||'wishlist';if(rating)rating.value=String(e?.rating||0);if(note)note.value=e?.note||'';}
function cmePhase74Remove(id){const d=cmePhase74Load();d.entries=(d.entries||[]).filter(x=>x.id!==id);cmePhase74SaveState(d);cmePhase62RenderDayMap(cmePhase63State().selectedDay);}
function cmePhase74Panel(){const all=cmePhase72FlattenAttractions(),d=cmePhase74Load(),entries=(d.entries||[]).slice().sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))),counts={visited:0,wishlist:0,favorite:0,notInterested:0};entries.forEach(x=>{if(counts[x.status]!==undefined)counts[x.status]++});return `<section class="cme-phase74-panel"><strong>Personal travel memory · Phase 74</strong><p>Track places you have visited, want to visit, love, or prefer not to see recommended. Stored locally on this device.</p><div class="cme-phase74-summary"><span class="cme-phase74-chip">Visited ${counts.visited}</span><span class="cme-phase74-chip">Wishlist ${counts.wishlist}</span><span class="cme-phase74-chip">Favorites ${counts.favorite}</span><span class="cme-phase74-chip">Hidden ${counts.notInterested}</span></div><div class="cme-phase74-form"><label>Attraction<select id="cme-phase74-attraction" onchange="cmePhase74LoadSelected()"><option value="">Select a place</option>${all.map(r=>`<option value="${String(r.id).replace(/&/g,'&amp;').replace(/"/g,'&quot;')}">${escapeHtml(r.names?.en||r.id)} · ${escapeHtml(r._cityName||r.cityId||'')}</option>`).join('')}</select></label><label>Memory status<select id="cme-phase74-status"><option value="visited">Visited</option><option value="wishlist">Wishlist</option><option value="favorite">Favorite</option><option value="notInterested">Not interested</option><option value="unmarked">Clear status</option></select></label><label>Your rating<select id="cme-phase74-rating"><option value="0">Not rated</option><option value="1">★ 1</option><option value="2">★ 2</option><option value="3">★ 3</option><option value="4">★ 4</option><option value="5">★ 5</option></select></label><label>Personal note<textarea id="cme-phase74-note" rows="2" placeholder="What did you like? Any tips for next time?"></textarea></label></div><div class="cme-phase74-actions"><button type="button" onclick="cmePhase74Save()">Save travel memory</button></div><small id="cme-phase74-feedback" class="cme-phase74-note">Feedback helps personalize future recommendations. No account sync is enabled.</small>${entries.length?`<strong>Recent memories</strong><div class="cme-phase74-list">${entries.slice(0,8).map(x=>`<div class="cme-phase74-entry"><b>${escapeHtml(x.name||x.id)}</b> · ${escapeHtml(cmePhase74Label(x.status))}${x.rating?` · ${'★'.repeat(x.rating)}`:''}<small>${escapeHtml(x.city||'')} ${x.note?`· ${escapeHtml(x.note)}`:''}</small><button type="button" onclick="cmePhase74Remove('${String(x.id).replace(/'/g,"\\'")}')">Remove memory</button></div>`).join('')}</div>`:'<small>No travel memories recorded yet.</small>'}<p class="cme-phase74-note">Visited and Not interested places are excluded from alternative recommendations. Favorites, wishlist and positive ratings can boost matches. Records can be removed individually.</p></section>`;}


const CME_PHASE75_LABELS={history:'History & culture',nature:'Nature',food:'Food',photography:'Photography',art:'Art & museums',shopping:'Shopping',architecture:'Architecture',relaxation:'Relaxation'};
function cmePhase75Analytics(){const entries=cmePhase74Load().entries||[],all=cmePhase72FlattenAttractions(),visited=entries.filter(x=>x.status==='visited'),cities=new Set(visited.map(x=>x.city).filter(Boolean)),ratings=entries.filter(x=>Number(x.rating)>0),avg=ratings.length?ratings.reduce((a,x)=>a+Number(x.rating),0)/ratings.length:0,counts={};Object.keys(cmePhase73Categories).forEach(k=>counts[k]=0);visited.forEach(m=>{const r=all.find(x=>x.id===m.id);if(!r)return;const text=((r.names?.en||'')+' '+(r.summary?.en||'')+' '+(r.category||'')+' '+(r.highlights||[]).join(' ')).toLowerCase();Object.entries(cmePhase73Categories).forEach(([k,terms])=>{if(terms.some(t=>text.includes(t)))counts[k]++;});});const visitedIds=new Set(entries.filter(x=>['visited','notInterested'].includes(x.status)).map(x=>x.id)),wishlistIds=new Set(entries.filter(x=>x.status==='wishlist').map(x=>x.id)),profile=cmePhase73Load(),suggestions=all.filter(r=>!visitedIds.has(r.id)).map(r=>{const p=cmePhase73Score(r,profile);const city=r._cityName||r.cityId||'Unknown city';const cityPenalty=cities.has(city)?-8:0;const unified=cmePhase86Score(r,city),score=unified.score+cityPenalty;return {r,score,city,matched:p.matched,reasons:unified.reasons};}).sort((a,b)=>b.score-a.score).slice(0,5);return {entries,visited,cities,ratings,avg,counts,suggestions,wishlist:wishlistIds.size,favorites:entries.filter(x=>x.status==='favorite').length,hidden:entries.filter(x=>x.status==='notInterested').length};}
const CME_PHASE85_KEY='cme-phase85-adaptive-profile-v1';
function cmePhase85Analyze(){const feedback=cmeRecommendationFeedbackRead(),all=cmePhase72FlattenAttractions(),weights={},evidence={};Object.keys(cmePhase73Categories).forEach(k=>{weights[k]=0;evidence[k]=0;});let liked=0,disliked=0,visited=0;Object.entries(feedback).forEach(([key,value])=>{const parts=key.split('::'),city=parts.shift(),name=parts.join('::'),item=all.find(r=>(r._cityName||r.cityId||'')===city&&(r.names?.en||r.id||'').trim().toLowerCase()===name)||all.find(r=>(r.names?.en||r.id||'').trim().toLowerCase()===name);if(!item)return;const status=value?.status;if(status==='liked')liked++;if(status==='disliked')disliked++;if(status==='visited')visited++;if(!['liked','disliked'].includes(status))return;const text=((item.names?.en||'')+' '+(item.summary?.en||'')+' '+(item.category||'')+' '+(item.highlights||[]).join(' ')+' '+(item.visitorTips||[]).join(' ')).toLowerCase();Object.entries(cmePhase73Categories).forEach(([cat,terms])=>{if(terms.some(t=>text.includes(t))){weights[cat]+=(status==='liked'?2:-2);evidence[cat]++;}});});const ranked=Object.entries(weights).filter(([k,v])=>v!==0).sort((a,b)=>b[1]-a[1]);return {weights,evidence,ranked,liked,disliked,visited,total:liked+disliked,confidence:liked+disliked<3?'Early signals':liked+disliked<8?'Emerging pattern':'More feedback available'};}
function cmePhase85Adjustment(item){const a=cmePhase85Analyze(),text=((item.names?.en||'')+' '+(item.summary?.en||'')+' '+(item.category||'')+' '+(item.highlights||[]).join(' ')).toLowerCase();let score=0;Object.entries(a.weights).forEach(([cat,w])=>{const terms=cmePhase73Categories[cat]||[];if(w&&terms.some(t=>text.includes(t)))score+=Math.max(-6,Math.min(6,w*1.5));});return score;}
const CME_PHASE86_LABELS={favorite:'Favorite',wishlist:'Wishlist',rating:'Rating',profile:'Traveler profile',feedback:'Feedback',adaptive:'Adaptive profile'};
