function cmePhase86Feedback(item,city){const target=city||item?._cityName||item?.cityId||'',name=(item?.names?.en||item?.id||'').trim().toLowerCase();if(!target||!name)return null;return cmeRecommendationFeedbackRead()[String(target)+'::'+name]||null;}
function cmePhase86Score(item,city){if(!item)return {score:0,excluded:false,reasons:[],memory:null,feedback:null};const memory=cmePhase86Memory(item),feedback=cmePhase86Feedback(item,city),profile=cmePhase73Load(),personal=cmePhase73Score(item,profile),adaptive=cmePhase85Adjustment(item);let score=personal.score+adaptive+cmeRecommendationFeedbackScore(city||item._cityName||item.cityId,item),reasons=[];if(personal.matched?.length)reasons.push('Traveler profile: '+personal.matched.join(', '));if(adaptive)reasons.push('Adaptive interests');if(feedback?.status==='liked'){score+=5;reasons.push('Liked');}if(feedback?.status==='disliked'){score-=8;reasons.push('Not for me');}if(memory?.status==='favorite'){score+=18;reasons.push('Favorite');}if(memory?.status==='wishlist'){score+=10;reasons.push('Wishlist');}if(memory?.rating>=4){const n=Math.min(12,(memory.rating-3)*6);score+=n;reasons.push('Positive rating');}if(memory?.rating>0&&memory.rating<=2){score-=18;reasons.push('Low rating');}if(memory?.status==='visited')reasons.push('Visited');if(memory?.status==='notInterested')reasons.push('Not interested');let excluded=['visited','notInterested'].includes(memory?.status)||['visited','disliked'].includes(feedback?.status);score+=cmePhase88Adjustment(item,score);const settings=cmePhase88Load();if(settings.includeVisited&&memory?.status==='visited')excluded=false;return {score,excluded,reasons,memory,feedback,personal,adaptive};}
function cmePhase86Reason(item,city){const r=cmePhase86Score(item,city);return r.reasons.length?r.reasons.join(' · '):'Available content match';}

function cmePhase87Explain(item,city){if(!item)return {score:0,confidence:'No signals',components:[],reasons:[]};const base=cmePhase86Score(item,city),personal=base.personal?.score||0,adaptive=Number(base.adaptive)||0,feedbackScore=Number(cmeRecommendationFeedbackScore(city||item._cityName||item.cityId,item))||0,memory=base.memory,feedback=base.feedback;const components=[{label:'Explicit preferences',score:personal},{label:'Adaptive interests',score:adaptive},{label:'Feedback signal',score:feedbackScore},{label:'Like / dislike',score:feedback?.status==='liked'?5:feedback?.status==='disliked'?-8:0},{label:'Favorite',score:memory?.status==='favorite'?18:0},{label:'Wishlist',score:memory?.status==='wishlist'?10:0},{label:'Rating',score:memory?.rating>=4?Math.min(12,(memory.rating-3)*6):memory?.rating>0&&memory.rating<=2?-18:0}].filter(x=>x.score!==0);const positive=components.filter(x=>x.score>0).length,negative=components.filter(x=>x.score<0).length;const confidence=components.length>=3?'Several signals':components.length===2?'Some signals':components.length===1?'Limited signals':'No personal signals';return {score:base.score,excluded:base.excluded,components,reasons:base.reasons,confidence,positive,negative};}
function cmePhase87Panel(){const all=cmePhase72FlattenAttractions(),ranked=all.map(item=>({item,ex:cmePhase87Explain(item,item._cityName||item.cityId)})).filter(x=>!x.ex.excluded).sort((a,b)=>b.ex.score-a.ex.score).slice(0,3);return `<section class="cme-phase87-panel"><strong>Why these recommendations? · Phase 87</strong><p>Scores are broken into visible preference, feedback and memory signals so you can inspect the ranking.</p>${ranked.length?ranked.map((x,i)=>`<div class="cme-phase87-item"><b>${i+1}. ${escapeHtml(x.item.names?.en||x.item.id)}</b><small>${escapeHtml(x.item._cityName||x.item.cityId||'')} · total ${x.ex.score} · ${escapeHtml(x.ex.confidence)}</small><div class="cme-phase87-breakdown">${x.ex.components.length?x.ex.components.map(c=>`<span>${escapeHtml(c.label)} ${c.score>0?'+':''}${c.score}</span>`).join(''):'<span>No personal signals</span>'}</div><small>${escapeHtml(x.ex.reasons.join(' · ')||'General content match')}</small></div>`).join(''):'<small>No eligible attraction records available.</small>'}<p class="cme-phase87-note">This is a transparent heuristic breakdown, not a probability or AI explanation. Scores are relative ranking signals; missing data is not treated as evidence.</p></section>`;}

const CME_PHASE88_KEY='cme-phase88-recommendation-controls-v1';
const CME_PHASE88_DEFAULTS={style:'personalized',diversity:45,includeVisited:false,weights:{}};
