function cmePhase88Save(v){try{localStorage.setItem(CME_PHASE88_KEY,JSON.stringify(v));}catch(e){}return v;}
function cmePhase88Text(item){return ((item?.names?.en||'')+' '+(item?.summary?.en||'')+' '+(item?.category||'')+' '+(item?.highlights||[]).join(' ')).toLowerCase();}
function cmePhase88Adjustment(item){const s=cmePhase88Load(),text=cmePhase88Text(item);let score=0;const signals={popular:['popular','famous','iconic','landmark','must-see','top attraction','well-known','著名','热门','地标'],niche:['hidden gem','local favorite','quiet','alley','neighborhood','traditional craft','less-known','小众','巷','街区','老店']};if(s.style==='popular'&&signals.popular.some(t=>text.includes(t)))score+=7;if(s.style==='niche'&&signals.niche.some(t=>text.includes(t)))score+=7;Object.entries(s.weights||{}).forEach(([cat,w])=>{const terms=cmePhase73Categories[cat]||[];if(Number(w)&&terms.some(t=>text.includes(t)))score+=Number(w);});return score;}
