const CME_ORIGINAL_TEXT=new WeakMap(),CME_ORIGINAL_ATTRS=new WeakMap();function applyCmePageTranslations(locale){const dict=CME_PAGE_TRANSLATIONS[locale]||{};const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{if(!CME_ORIGINAL_TEXT.has(n))CME_ORIGINAL_TEXT.set(n,n.nodeValue);const original=CME_ORIGINAL_TEXT.get(n),raw=original.trim();n.nodeValue=dict[raw]?original.replace(raw,dict[raw]):original;});document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{if(!CME_ORIGINAL_ATTRS.has(el))CME_ORIGINAL_ATTRS.set(el,{placeholder:el.getAttribute('placeholder')});const original=CME_ORIGINAL_ATTRS.get(el).placeholder;el.setAttribute('placeholder',dict[original]||original);});document.querySelectorAll('button[aria-label],input[aria-label],select[aria-label]').forEach(el=>{if(!CME_ORIGINAL_ATTRS.has(el))CME_ORIGINAL_ATTRS.set(el,{...(CME_ORIGINAL_ATTRS.get(el)||{}),ariaLabel:el.getAttribute('aria-label')});const original=CME_ORIGINAL_ATTRS.get(el).ariaLabel; if(original)el.setAttribute('aria-label',dict[original]||original);});}
function setCmeLanguage(locale){if(!CME_UI_TRANSLATIONS[locale])locale='en';cmeLocale=locale;try{CMEStorage.setItem(CME_LOCALE_KEY,locale)}catch(e){}document.documentElement.lang=locale;const select=document.getElementById('cme-language');if(select)select.value=locale;applyCmePageTranslations(locale);renderExperiences();if(cmeModalCity&&document.getElementById('modal')?.classList.contains('open')){const city=cmeModalCity,index=cmeModalAttractionIndex;openCity(city).then(()=>{if(index!==null)showAttraction(city,index);});}}
function initCmeLanguage(){let locale='en';try{locale=CMEStorage.getItem(CME_LOCALE_KEY)||'en'}catch(e){}setCmeLanguage(locale);}
let cmeAttractionsLoaded=false;
let cmeCityRecords={};
let cmeModalCity=null;
let cmeModalAttractionIndex=null;
async function loadAttractionsFromJson(){if(cmeAttractionsLoaded)return;try{const [attractionResponse,cityResponse]=await Promise.all([fetch('./data/attractions.json'),fetch('./data/cities.json')]);if(!attractionResponse.ok||!cityResponse.ok)throw new Error('Content data request failed');const records=await attractionResponse.json();const cityRecords=await cityResponse.json();if(!Array.isArray(records)||!Array.isArray(cityRecords))throw new Error('Invalid content data');const cityNames=Object.fromEntries(cityRecords.map(c=>[c.id,c.name]));cmeCityRecords=Object.fromEntries(cityRecords.map(c=>[c.name,c]));const grouped={};records.forEach(r=>{const city=cityNames[r.cityId];if(!city)return;(grouped[city]||(grouped[city]=[])).push(r);});Object.keys(grouped).forEach(city=>grouped[city].sort((a,b)=>attractionName(a).localeCompare(attractionName(b))));attractionData=grouped;cmeAttractionsLoaded=true;populateAttractionCheckinOptions();renderCheckins();}catch(e){console.warn('Using embedded attraction fallback:',e.message)}}
function cityOverviewHtml(name){const city=cmeCityRecords[name];if(!city)return '';const themes=(city.themes||[]).map(t=>`<span style="display:inline-block;margin:3px;padding:5px 9px;border-radius:20px;background:#eef2e9;color:#405b43;font-size:12px">${escapeHtml(t)}</span>`).join('');return `<section class="city-content-overview" style="margin:16px 0;padding:18px;border:1px solid #e3e8df;border-radius:16px;background:#fafbf7"><p class="step-label">${cmeT("snapshot")}</p><p>${escapeHtml(cmeLocalizedCityIntro(name))}</p><p><b>${cmeT("suggested")}</b> ${escapeHtml(city.recommendedDays||'Flexible')}</p><div>${themes}</div><small style="display:block;margin-top:10px;color:#718076">${cmeT("status")} ${escapeHtml(city.contentStatus||'draft')}</small></section>`}
const attractionAuditSources={
'Forbidden City':{name:'Palace Museum official visitor information',url:'https://intl.dpm.org.cn/visit',note:'Official visitor page currently states seasonal opening hours, advance ticketing, passport details for foreign visitors, and a daily visitor cap. Check the official ticket platform before travel.'},
'Great Wall':{name:'Mutianyu Great Wall official visitor information',url:'https://en.mutianyugreatwall.com/article/4DlCYuBZ75h',note:'Official visitor page includes seasonal access and ticket information; operating arrangements can change, especially for cable cars and special events.'},
'Temple of Heaven':{name:'Beijing municipal official visitor guide',url:'https://english.beijing.gov.cn/specials/parktours/guidevisitors/templeofheaven/index.html',note:'Official guide includes seasonal park hours, separate attraction hours, ticket options and passport booking guidance.'},
'Summer Palace':{name:'Beijing municipal official visitor guide',url:'https://english.beijing.gov.cn/specials/parktours/guidevisitors/summerpalace/index.html',note:'Official guide includes seasonal hours, separate paid areas, ticket options and passport booking guidance.'},
'798 Art District':{name:'Beijing municipal official guide · 798·751 Zone',url:'https://english.beijing.gov.cn/travellinginbeijing/attractions/202603/t20260323_4563864.html',note:'Official guide describes the open-access district and notes that exhibitions/events may have separate tickets or reservations. Individual galleries and venues set their own hours.'},
'Confucius Temple & Imperial College':{name:'Beijing municipal official visitor guide',url:'https://english.beijing.gov.cn/specials/ticketing/museums/202409/t20240929_3909675.html',note:'Official visitor guide lists the combined museum, visitor hours, Monday closure, admission and ticketing channels. Recheck dynamic details before travel.'}
};
const attractionBookingGuidance={
 'Forbidden City':{status:'official-guidance',title:'Booking & entry for foreign visitors',steps:['Use the Palace Museum official English booking website and select passport as your identity document.','Enter your passport details carefully and keep the booking confirmation.','Bring the original passport used for booking; official Beijing guidance says foreign visitors enter through the manual ticket-check channel at Meridian Gate (South Gate).','Do not rely on same-day tickets; check the official ticket page for the current booking window and availability.'],fallback:'If the booking website or phone verification fails, contact the Palace Museum English-service hotline listed by Beijing government guidance before travelling.',sources:[{label:'Palace Museum official visitor page',url:'https://intl.dpm.org.cn/visit'},{label:'Beijing government booking FAQ',url:'https://english.beijing.gov.cn/12345hotline/faqs/all/202506/t20250620_4117980.html'}]},
 'Temple of Heaven':{status:'official-guidance',title:'Booking & entry for foreign visitors',steps:['Foreign visitors can book online through the official Temple of Heaven WeChat account, using the passport and identity details required by the ticket channel.','For the park and separately ticketed scenic areas, check which ticket type you need; the Hall of Prayer for Good Harvests, Echo Wall and Circular Mound Altar may require a separate scenic-area ticket or combo ticket.','Save the e-ticket QR code and bring the identity document used for purchase.','If online booking is unavailable, Beijing government guidance says visitors may ask the park comprehensive service counter about staff-assisted purchase; same-day QR purchase may be available if capacity remains.'],fallback:'Official Beijing guidance lists staffed service counters as an offline option. Confirm the current ticket and payment arrangements before visiting.',sources:[{label:'Beijing official ticketing guide',url:'https://english.beijing.gov.cn/specials/ticketing/index.html'},{label:'Beijing municipal parks booking guide',url:'https://english.beijing.gov.cn/quickguideservices/purchaseparktickets/'}]},
 'Summer Palace':{status:'official-guidance',title:'Booking & entry for foreign visitors',steps:['The official municipal-park platform provides online booking, but current Beijing government guidance says online ticket purchases require a mainland China mobile number.','If you cannot complete online booking, use the park entrance comprehensive service window and ask for staff-assisted ticket purchase with your passport.','Check whether you need a general park ticket or a ticket for separately charged attractions.','Keep your passport and ticket confirmation available at entry.'],fallback:'Beijing government guidance confirms an offline staff-assisted ticket option for visitors unable to use online booking. Confirm ticket type and availability at the park.',sources:[{label:'Beijing government FAQ on foreign phone numbers',url:'https://english.beijing.gov.cn/12345hotline/faqs/all/202506/t20250620_4117980.html'},{label:'Official Summer Palace visitor guide',url:'https://english.beijing.gov.cn/specials/ticketing/index.html'}]},
 'Great Wall':{status:'section-specific-guidance',title:'Choose your Great Wall section before booking',steps:['“Great Wall” is not one ticket or entrance. Choose the section (for example Mutianyu or Badaling) before booking transport and tickets.','For Mutianyu, the official site says foreign visitors can reserve with a passport and present the original passport for entry; advance booking is recommended.','Mutianyu tickets and transport add-ons (shuttle, cable car, ropeway or slide) are separate choices. Check the official site for the entrance gate and the operating hours of the specific service you choose.','Do not apply Mutianyu rules to Badaling or another section.'],fallback:'If you have not chosen a section, use the city guide to compare access and difficulty first. Verify the selected section’s official ticket channel.',sources:[{label:'Mutianyu official visitor notice',url:'https://en.mutianyugreatwall.com/article/4DlCYuBZ75h'},{label:'Mutianyu official ticketing site',url:'https://en.mutianyugreatwall.com/'}]},
 '798 Art District':{status:'venue-specific-guidance',title:'Entry & exhibition tickets',steps:['The 798·751 district itself is generally open-access; you do not normally need one district-wide admission ticket.','Individual galleries, exhibitions, events and special venues may have their own ticket, reservation, opening-day and entry requirements.','Check the specific exhibition or venue you want to visit, rather than assuming the entire district follows one schedule.'],fallback:'If you are visiting for a particular exhibition or event, confirm directly with that venue before travelling.',sources:[{label:'Beijing official 798·751 Zone guide',url:'https://english.beijing.gov.cn/travellinginbeijing/attractions/202603/t20260323_4563864.html'}]},
 'Confucius Temple & Imperial College':{status:'official-guidance',title:'Tickets & visit planning',steps:['Check the official combined visitor information for current opening days, ticket price and ticketing channel.','The official Beijing guide lists the museum complex and visitor information; rules may differ for special exhibitions or events.','Bring the passport or identity document used for any booking and confirm current ticket availability before travelling.'],fallback:'The attraction’s official visitor information is the source of truth for current ticketing and closure notices.',sources:[{label:'Beijing official visitor guide',url:'https://english.beijing.gov.cn/specials/ticketing/museums/202409/t20240929_3909675.html'}]}
};
function renderAttractionBookingGuidance(name){const g=attractionBookingGuidance[name];if(!g)return '';return `<section class="tip attraction-booking-guidance"><b>🎟️ ${escapeHtml(g.title)}</b><ol>${g.steps.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ol><p><strong>Backup plan:</strong> ${escapeHtml(g.fallback)}</p><small>Guidance status: ${escapeHtml(g.status)} · Confirm current rules before travel.</small><ul class="booking-source-links">${g.sources.map(x=>`<li><a href="${escapeHtml(x.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(x.label)} ↗</a></li>`).join('')}</ul></section>`}
function attractionName(item){if(Array.isArray(item))return item[0];const names=item.names||{};return names[cmeLocale]||names.en||names['zh-Hans']||item.slug||'Attraction';}
function attractionChinese(item){return Array.isArray(item)?item[1]:(item.names?.['zh-Hans']||'');}
function attractionSummary(item){if(Array.isArray(item))return item[2];const summaries=item.summary||{};return summaries[cmeLocale]||summaries.en||summaries['zh-Hans']||'';}
function attractionSecondaryName(item){const chinese=attractionChinese(item);return ['zh-Hans','zh-Hant'].includes(cmeLocale)||!chinese||chinese===attractionName(item)?'':chinese;}
function cmeLocalizedCityIntro(name){const city=cmeCityRecords[name];if(!city)return '';const locales=city.introLocales||{};return locales[cmeLocale]||city.intro||locales.en||'';}
function attractionTips(item){return Array.isArray(item)?[item[3]]:(item.visitorTips||[]);}
function attractionDuration(item){return Array.isArray(item)?item[4]:(item.visitDuration?.display||'Duration varies');}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function copyAttractionAddress(address){if(!address){alert('No address available to copy yet.');return;}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(address).then(()=>alert('Address copied.')).catch(()=>fallbackCopyAddress(address));}else fallbackCopyAddress(address)}
function fallbackCopyAddress(address){const el=document.createElement('textarea');el.value=address;el.style.position='fixed';el.style.opacity='0';document.body.appendChild(el);el.select();try{document.execCommand('copy');alert('Address copied.')}catch(e){alert('Please copy this address manually: '+address)}el.remove()}
function showAttraction(city,index){
 const list=attractionData[city]||[];const item=list[index];if(!item)return;cmeModalCity=city;cmeModalAttractionIndex=index;
 const name=attractionName(item),content=document.getElementById('modal-content');
 const audit=city==='Beijing'&&attractionAuditSources[name]?attractionAuditSources[name]:null;
 const tips=attractionTips(item).filter(Boolean).map(t=>`<li>${escapeHtml(t)}</li>`).join('');
 const highlights=Array.isArray(item)?[]:(item.highlights||[]);
 const ticket=item.ticketing||{},hours=item.openingHours||{};
 const verified=ticket.verificationStatus==='verified'&&ticket.lastVerifiedAt;
 const hoursVerified=hours.verificationStatus==='verified'&&hours.lastVerifiedAt;
 const sourceReviewDates=sourceLinks.map(x=>x.checkedAt).filter(Boolean);
 const latestSourceReview=sourceReviewDates.sort().slice(-1)[0]||ticket.lastVerifiedAt||hours.lastVerifiedAt||'';
 const booking=ticket.officialBookingUrl,sourceLinks=Array.isArray(item.sources)?item.sources.filter(x=>x.url):[];
 const status=Array.isArray(item)?'legacy content':item.contentStatus||'draft';
 const address=item.address||'',addressChinese=item.addressChinese||'',addressStatus=item.addressVerificationStatus||'unverified';const mapQuery=addressChinese||address||`${name}, ${city}, China`;const mapsUrl='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(mapQuery);
 const ticketDetails=verified?(ticket.priceNotes||'Ticket details verified; check the official source for current availability.'):(cmeT('notVerified'));
 const hoursDetails=hours.text&&hoursVerified?hours.text:cmeT('hoursNotVerified');
 const verifiedDate=ticket.lastVerifiedAt||hours.lastVerifiedAt||'';
 content.innerHTML=`<div class="attraction-detail">
 <button class="back-attractions" onclick="openCity('${escapeHtml(city)}')">← ${cmeT('back')} ${escapeHtml(cmeLocalizedCity(city))}</button>
 <p class="step-label">${cmeT('guide')} · ${escapeHtml(cmeLocalizedCity(city).toUpperCase())}</p>
 <h3>${escapeHtml(attractionName(item))} <span style="font-weight:500;color:#718076">${escapeHtml(attractionSecondaryName(item))}</span></h3>
 <p>${escapeHtml(attractionSummary(item))}</p>
 ${address||addressChinese?`<section class="tip attraction-address"><b>📍 Address / 地址</b>${address?`<p><strong>English address</strong><br>${escapeHtml(address)}</p><div class="address-actions"><button class="secondary" onclick="copyAttractionAddress('${escapeHtml(address)}')">Copy English address</button></div>`:''}${addressChinese?`<p class="address-chinese"><strong>中文地址（打车用）</strong><br>${escapeHtml(addressChinese)}</p><div class="address-actions"><button class="secondary" onclick="copyAttractionAddress('${escapeHtml(addressChinese)}')">Copy Chinese address for taxi apps</button></div>`:''}<div class="address-actions"><a class="secondary" href="${escapeHtml(mapsUrl)}" target="_blank" rel="noopener noreferrer">Open in Google Maps ↗</a></div><small>Address status: ${escapeHtml(addressStatus)}</small></section>`:`<section class="tip attraction-address"><b>📍 Location / 位置</b><p>Verified address is not available yet.</p><p>中文地址暂未核实，暂不能提供打车复制地址。</p><div class="address-actions"><a class="secondary" href="${escapeHtml(mapsUrl)}" target="_blank" rel="noopener noreferrer">Search on Google Maps ↗</a><article class="verification-card"><span class="verification-status">PHASE 5 · SEASONAL OPERATIONS REVIEW</span><h3>Beijing · seasonal hours & ticket zones</h3><p><b>Confucius Temple & Imperial College:</b> venue booking information reports real-name reservations, a daily quota and seasonal hours; a municipal visitor listing differs on opening time. Reservation status appeared paused during review—confirm directly before travelling.</p><p><b>Summer Palace:</b> the main park and separately ticketed sites have different hours and prices. Some paid sites close Mondays except statutory holidays.</p><p><b>Temple of Heaven:</b> the park gates stay open later than the paid scenic buildings. The paid buildings normally close Mondays except statutory holidays.</p><small>Official-source review: 22 November 2026 · Dynamic prices, schedules and reservation status must be rechecked.</small><div class="verification-links"><a href="https://kmgzj.hdwbcloud.com/" target="_blank" rel="noopener noreferrer">Confucius Temple · reservation portal ↗</a><a href="https://s.visitbeijing.com.cn/attraction/117801" target="_blank" rel="noopener noreferrer">Visit Beijing · Confucius Temple listing ↗</a><a href="https://yllhj.beijing.gov.cn/ztxx/kpjd/202312/t20231222_3508035.shtml" target="_blank" rel="noopener noreferrer">Summer Palace · Beijing Municipal Landscaping Bureau ↗</a><a href="https://s.visitbeijing.com.cn/attraction/101407" target="_blank" rel="noopener noreferrer">Summer Palace · Visit Beijing ↗</a><a href="https://data.beijing.gov.cn/publish/bjdata/zyml/wnkfsj/63f3ccb5324d460091913b8d818686d7.htm" target="_blank" rel="noopener noreferrer">Temple of Heaven · Beijing government data ↗</a><a href="https://s.visitbeijing.com.cn/index.php/attraction/101409" target="_blank" rel="noopener noreferrer">Temple of Heaven · Visit Beijing ↗</a></div></article></div></section>`}
 ${renderAttractionBookingGuidance(name)}
 ${highlights.length?`<h3>Highlights</h3><ul>${highlights.map(h=>`<li>${escapeHtml(h)}</li>`).join('')}</ul>`:''}
 <h3>${cmeT('tips')}</h3>${tips?`<ul>${tips}</ul>`:'<p>Tips are being prepared.</p>'}
 <div class="tip attraction-facts"><b>Suggested time:</b> ${escapeHtml(attractionDuration(item))}
 <br><b>Opening hours:</b> ${escapeHtml(hoursDetails)}
 <br><b>Ticketing:</b> ${escapeHtml(ticketDetails)}
 ${booking&&verified?`<br><a href="${escapeHtml(booking)}" target="_blank" rel="noopener noreferrer">Official booking ↗</a>`:''}
 
 ${verifiedDate?`<br><b>Last verified:</b> ${escapeHtml(verifiedDate)}`:''}
 <br><small>Opening hours, prices, booking rules and access can change. Confirm with official sources before visiting.</small></div>
 ${sourceLinks.length?`<h3>Sources & review status</h3><p><small>Source review date: ${escapeHtml(latestSourceReview||'not recorded')} · Ticketing: ${escapeHtml(ticket.verificationStatus||'unverified')} · Opening hours: ${escapeHtml(hours.verificationStatus||'unverified')}</small></p><ul>${sourceLinks.map(x=>`<li><a href="${escapeHtml(x.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(x.label||x.name||x.url)} ↗</a>${x.checkedAt?` <small>(${escapeHtml(x.checkedAt)})</small>`:''}</li>`).join('')}</ul>`:''}
 ${audit?`<div class="tip source-audit"><b>Official source checked · ${escapeHtml(verifiedDate||'date not recorded')}</b><p>${escapeHtml(audit.note)}</p><a href="${escapeHtml(audit.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(audit.name)} ↗</a></div>`:''}
 <small class="content-status">Content status: ${escapeHtml(status)}</small></div>`;
}
const CME_ATTRACTION_THEMES={
 'shanghai-the-bund':'City & neighbourhoods','shanghai-yu-garden':'History & culture','shanghai-shanghai-tower':'Modern landmarks','shanghai-former-french-concession':'City & neighbourhoods',
 'beijing-forbidden-city':'History & culture','beijing-great-wall':'Nature & scenery','beijing-temple-of-heaven':'History & culture','beijing-summer-palace':'Nature & scenery','beijing-798-art-district':'City & neighbourhoods','beijing-confucius-temple-imperial-college':'History & culture',
 'guangzhou-canton-tower':'Modern landmarks','guangzhou-chen-clan-ancestral-hall':'History & culture','guangzhou-shamian-island':'City & neighbourhoods','guangzhou-yongqing-fang':'City & neighbourhoods',
 'shenzhen-shenzhen-bay-park':'Nature & scenery','shenzhen-lianhuashan-park':'Nature & scenery','shenzhen-huaqiangbei':'City & neighbourhoods','shenzhen-oct-loft':'City & neighbourhoods',
 'chengdu-chengdu-panda-base':'Nature & scenery','chengdu-people-s-park':'City & neighbourhoods','chengdu-wuhou-shrine-jinli':'History & culture','chengdu-kuanzhai-alleys':'City & neighbourhoods',
 'chongqing-hongya-cave':'City & neighbourhoods','chongqing-jiefangbei':'City & neighbourhoods','chongqing-liziba':'Modern landmarks','chongqing-yangtze-cableway':'Nature & scenery',
 'harbin-central-street':'City & neighbourhoods','harbin-saint-sophia-cathedral':'History & culture','harbin-ice-and-snow-world':'Seasonal attractions','harbin-sun-island':'Nature & scenery',
 'xinjiang-kanas':'Nature & scenery','xinjiang-hemu':'Nature & scenery','xinjiang-sayram-lake':'Nature & scenery','xinjiang-kashgar-old-city':'History & culture'
};
function attractionTheme(item){const id=item?.id||'';return CME_ATTRACTION_THEMES[id]||'Other attractions';}
function filterCityAttractions(city,query){const browser=document.querySelector('.attraction-browser[data-city="'+city+'"]');if(!browser)return;const q=(query||'').trim().toLowerCase();browser.querySelectorAll('.attraction-theme-group').forEach(group=>{let visible=0;group.querySelectorAll('.attraction-button').forEach(btn=>{const show=!q||(btn.dataset.search||'').includes(q);btn.hidden=!show;if(show)visible++;});group.hidden=visible===0;});const count=browser.querySelector('.attraction-search-count');if(count)count.textContent=q?`${browser.querySelectorAll('.attraction-button:not([hidden])').length} matches`:'Browse by topic';}
function addAttractionBrowser(city){const content=document.getElementById('modal-content');const items=attractionData[city]||[];if(!items.length)return;const picks=cmeRecommendationPanel(city,items);if(picks)content.insertAdjacentHTML('beforeend',picks);const browser=document.createElement('div');browser.className='attraction-browser';browser.dataset.city=city;const groups={};items.forEach((item,i)=>{const theme=attractionTheme(item);(groups[theme]||(groups[theme]=[])).push({item,i});});const order=['History & culture','Nature & scenery','City & neighbourhoods','Modern landmarks','Seasonal attractions','Other attractions'];browser.innerHTML=`<div class="attraction-browser-head"><h3>${cmeT("attractions")}</h3><p>Choose a topic to browse instead of viewing every attraction at once.</p><input class="attraction-search" type="search" placeholder="Search attractions…" aria-label="Search attractions" oninput="filterCityAttractions('${escapeHtml(city)}',this.value)"><small class="attraction-search-count">Browse by topic</small></div>${order.filter(theme=>groups[theme]?.length).map(theme=>`<details class="attraction-theme-group"><summary><strong>${theme}</strong><span>${groups[theme].length} ${groups[theme].length===1?'place':'places'}</span></summary><div class="attraction-grid">${groups[theme].map(({item,i})=>`<button class="attraction-button" data-search="${escapeHtml((attractionName(item)+' '+attractionChinese(item)+' '+attractionSummary(item)+' '+theme).toLowerCase())}" onclick="showAttraction('${escapeHtml(city)}',${i})"><span>📍</span><span><strong>${escapeHtml(attractionName(item))}</strong><small>${escapeHtml(attractionChinese(item))} · ${cmeT("openGuide")}</small></span></button>`).join('')}</div></details>`).join('')}`;content.appendChild(browser);}

function showRestaurantsForCity(city){closeModal();const select=document.getElementById('restaurant-city-select');const known=select&&[...select.options].some(o=>o.value===city);const search=document.getElementById('restaurant-search');if(known){if(search)search.value='';filterRestaurantCity(city,null);}else{if(select)select.value='all';restaurantCity='all';if(search)search.value=city;filterRestaurants();}document.getElementById('restaurants')?.scrollIntoView({behavior:'smooth'});}
async function openCity(name){cmeModalCity=name;cmeModalAttractionIndex=null;await loadAttractionsFromJson();document.getElementById('modal-title').textContent='📍 '+cmeLocalizedCity(name);document.getElementById('modal-content').innerHTML=cityOverviewHtml(name)+cities[name]+`<div class="city-restaurant-cta" style="margin:16px 0"><button type="button" class="primary" onclick="showRestaurantsForCity('${name.replace(/'/g,"\\'")}')">🍽️ ${cmeLocale==='zh-Hans'?'查看本城市餐厅':cmeLocale==='zh-Hant'?'查看本城市餐廳':cmeLocale==='fr'?'Voir les restaurants de cette ville':cmeLocale==='es'?'Ver restaurantes de esta ciudad':cmeLocale==='ja'?'この都市のレストランを見る':cmeLocale==='ko'?'이 도시의 레스토랑 보기':'View restaurants in this city'}</button></div>`;addAttractionBrowser(name);document.getElementById('modal').classList.add('open');document.body.style.overflow='hidden'}
function closeModal(){document.getElementById('modal').classList.remove('open');document.body.style.overflow=''}
function copyText(t){if(navigator.clipboard){navigator.clipboard.writeText(t).then(()=>alert('Copied!')).catch(()=>fallbackCopy(t))}else fallbackCopy(t)}
function fallbackCopy(t){let a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();alert('Copied!')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function restoreChecklistState(){const groups=[['.app-checklist input[type=checkbox]','cme-app-checklist-v1'],['#checklist .check-item input[type=checkbox]','cme-before-trip-v1']];groups.forEach(([selector,key])=>{let saved={};try{saved=JSON.parse(CMEStorage.getItem(key)||'{}')}catch(e){}document.querySelectorAll(selector).forEach((box,i)=>box.checked=!!saved[i]);});renderMyChina();}
// Persist checklist progress locally on this device; no account or server is required.
(function(){
 const groups=[['.app-checklist input[type=checkbox]','cme-app-checklist-v1'],['#checklist .check-item input[type=checkbox]','cme-before-trip-v1']];
 groups.forEach(([selector,key])=>{const boxes=[...document.querySelectorAll(selector)];let saved={};try{saved=JSON.parse(CMEStorage.getItem(key)||'{}')}catch(e){}
 boxes.forEach((box,i)=>{box.checked=!!saved[i];box.addEventListener('change',()=>{const state={};boxes.forEach((b,j)=>state[j]=b.checked);try{CMEStorage.setItem(key,JSON.stringify(state))}catch(e){}renderMyChina();})});
 });
})();
initCmeLanguage();
